html:
{#- Change of Employment Details letter, printed from an Employee Record Update Request.

     Every value comes from the request. The three fixed paragraphs of the approved letter
     (terms and conditions, closing, acknowledgement) are the only text typed in here: paste
     the exact approved wording between the quotes of the three variables below. A paragraph
     whose variable is empty is not printed. -#}
{%- set terms_and_conditions_statement = '' -%}
{%- set closing_statement = '' -%}
{%- set acknowledgement_statement = '' -%}

{#- Both the staging and the BA spellings of the terms fields are read. -#}
{%- set terms_required = doc.get('term_changes_required') or doc.get('properties_changes_required') -%}
{%- set term_rows = (doc.get('employment_terms') or doc.get('properties') or []) if terms_required else [] -%}
{%- set day_off_required = doc.get('day_off_terms_required') -%}
{%- set benefit_rows = (doc.get('benefit') or []) if doc.get('benefits_changes_required') else [] -%}
{%- set salary_required = doc.get('salary_update_required') -%}
{%- set component_rows = (doc.get('salary_structure_components') or []) if salary_required else [] -%}
{%- set employee_info = frappe.db.get_value('Employee', doc.employee, ['salutation', 'employee_name'], as_dict=True) if doc.employee else none -%}
{%- set employee_name = doc.employee_name or (employee_info.employee_name if employee_info else '') -%}
{%- set salutation = employee_info.salutation if employee_info else '' -%}
{%- set hr_user = frappe.db.get_single_value('HR Settings', 'custom_hr_manager') -%}
{%- set hr_manager = frappe.db.get_value('Employee', {'user_id': hr_user}, ['employee_name', 'designation'], as_dict=True) if hr_user else none -%}

{%- macro show_date(value) -%}{{ frappe.format(value, {'fieldtype': 'Date'}) if value else '' }}{%- endmacro -%}
{%- macro show_money(value) -%}{{ frappe.format(value, {'fieldtype': 'Currency'}) if value not in (none, '') else '' }}{%- endmacro -%}

<style>
    .coe-doc { font-family: Arial, Helvetica, sans-serif; color: #000; font-size: 12px; line-height: 1.5; }
    .coe-head { width: 100%; border: none; margin-bottom: 14px; }
    .coe-head td { border: none; padding: 0; vertical-align: middle; }
    .coe-logo { height: 46px !important; width: auto !important; max-width: 240px; object-fit: contain; }
    .coe-block { width: 100%; border-collapse: collapse; margin-bottom: 12px; table-layout: fixed; }
    .coe-block th, .coe-block td { border: 1px solid #000; padding: 6px 8px; vertical-align: middle; word-wrap: break-word; }
    .coe-block tr { page-break-inside: avoid; }
    .coe-section { background-color: #d9d9d9; font-weight: bold; text-align: center; }
    .coe-column { background-color: #f2f2f2; font-weight: bold; text-align: left; }
    .coe-label { width: 30%; font-weight: bold; }
    .coe-title { text-align: center; font-size: 15px; font-weight: bold; margin: 18px 0 14px 0; text-decoration: underline; }
    .coe-text { margin: 0 0 10px 0; text-align: justify; white-space: pre-line; }
    .coe-hr { margin: 14px 0 18px 0; font-weight: bold; }
    .coe-hr div { font-weight: normal; }
    .coe-sign { page-break-inside: avoid; }
    .coe-sign td { height: 52px; }
</style>

<div class="coe-doc">

    <table class="coe-head">
        <tr>
            <td>
                {%- if pow_logo_src() %}<img class="coe-logo" src="{{ pow_logo_src() }}" alt="">{% endif -%}
            </td>
        </tr>
    </table>

    <table class="coe-block">
        <tr>
            <td class="coe-label">{{ _('Employee ID') }}</td>
            <td>{{ doc.employee or '' }}</td>
        </tr>
        <tr>
            <td class="coe-label">{{ _('Employee Name') }}</td>
            <td>{{ employee_name }}</td>
        </tr>
        <tr>
            <td class="coe-label">{{ _('Designation') }}</td>
            <td>{{ doc.designation or '' }}</td>
        </tr>
        <tr>
            <td class="coe-label">{{ _('Project') }}</td>
            <td>{{ doc.get('project_allocation') or doc.get('project') or '' }}</td>
        </tr>
        <tr>
            <td class="coe-label">{{ _('Date') }}</td>
            <td>{{ show_date(doc.creation) }}</td>
        </tr>
    </table>

    <div class="coe-title">{{ _('CHANGE OF EMPLOYMENT DETAILS') }}</div>

    <p class="coe-text">
        {%- if salutation %}{{ _('Dear') }} {{ salutation }} {{ employee_name }},{% else %}{{ _('Dear') }} {{ employee_name }},{% endif -%}
    </p>

    <p class="coe-text"><b>{{ _('Effective Date of Change') }}:</b> {{ show_date(doc.effective_date_of_change) }}</p>

    {%- if term_rows or day_off_required %}
    <table class="coe-block">
        <tr><th class="coe-section" colspan="3">{{ _('Change of Employment Details') }}</th></tr>
        <tr>
            <th class="coe-column">{{ _('Terms') }}</th>
            <th class="coe-column">{{ _('Current Details') }}</th>
            <th class="coe-column">{{ _('New Details') }}</th>
        </tr>
        {%- for row in term_rows %}
        <tr>
            <td>{{ row.get('terms') or row.get('property') or '' }}</td>
            <td>{{ row.old_value or '' }}</td>
            <td>{{ row.new_value or '' }}</td>
        </tr>
        {%- endfor %}
        {%- if day_off_required %}
        <tr>
            <td>{{ _('Day Off Category') }}</td>
            <td>{{ doc.day_off_category_current_value or '' }}</td>
            <td>{{ doc.day_off_category_new_value or '' }}</td>
        </tr>
        <tr>
            <td>{{ _('Number of Days Off') }}</td>
            <td>{{ doc.number_of_days_off_current_value or '' }}</td>
            <td>{{ doc.number_of_days_off_new_value or '' }}</td>
        </tr>
        {%- endif %}
    </table>
    {%- endif %}

    {%- if benefit_rows %}
    <table class="coe-block">
        <tr><th class="coe-section" colspan="2">{{ _('Benefits') }}</th></tr>
        <tr>
            <th class="coe-column">{{ _('Benefit') }}</th>
            <th class="coe-column">{{ _('Description') }}</th>
        </tr>
        {%- for row in benefit_rows %}
        <tr>
            <td>{{ row.get('terms') or row.get('property') or '' }}</td>
            <td>{{ row.description or '' }}</td>
        </tr>
        {%- endfor %}
    </table>
    {%- endif %}

    {%- if salary_required %}
    <table class="coe-block">
        <tr><th class="coe-section" colspan="3">{{ _('Salary Update') }}</th></tr>
        <tr>
            <th class="coe-column">{{ _('Terms') }}</th>
            <th class="coe-column">{{ _('Current Details') }}</th>
            <th class="coe-column">{{ _('New Details') }}</th>
        </tr>
        <tr>
            <td>{{ _('Salary Structure') }}</td>
            <td>{{ doc.current_salary_structure or '' }}</td>
            <td>{{ doc.salary_new_value or '' }}</td>
        </tr>
        <tr>
            <td>{{ _('Base Salary') }}</td>
            <td>{{ show_money(doc.current_base_salary) }}</td>
            <td>{{ show_money(doc.base_new_value) }}</td>
        </tr>
    </table>
    {%- if component_rows %}
    <table class="coe-block">
        <tr>
            <th class="coe-column">{{ _('Terms') }}</th>
            <th class="coe-column">{{ _('Current Details') }}</th>
        </tr>
        {%- for row in component_rows %}
        <tr>
            <td>{{ row.salary_component or '' }}</td>
            <td>{{ show_money(row.amount) }}</td>
        </tr>
        {%- endfor %}
    </table>
    {%- endif %}
    {%- endif %}

    {%- if terms_and_conditions_statement %}
    <p class="coe-text">{{ terms_and_conditions_statement }}</p>
    {%- endif %}

    {%- if closing_statement %}
    <p class="coe-text">{{ closing_statement }}</p>
    {%- endif %}

    <div class="coe-hr">
        {{ hr_manager.employee_name if hr_manager else '' }}
        <div>{{ hr_manager.designation if hr_manager and hr_manager.designation else '' }}</div>
    </div>

    {%- if acknowledgement_statement %}
    <p class="coe-text">{{ acknowledgement_statement }}</p>
    {%- endif %}

    <table class="coe-block coe-sign">
        <tr><th class="coe-section" colspan="2">{{ _('Employee Acknowledgement') }}</th></tr>
        <tr>
            <td class="coe-label">{{ _('Employee Signature') }}</td>
            <td></td>
        </tr>
        <tr>
            <td class="coe-label">{{ _('Date') }}</td>
            <td></td>
        </tr>
    </table>

</div>
